<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Seeder: RekapHarianTanamSeeder
 * Provinsi Sumatera Selatan - Tahun 2025
 * Total Records: 2892 (241 kecamatan x 12 bulan)
 * 
 * CATATAN PENTING:
 * - kecamatan_id mengacu ke KecamatanSeeder (auto-increment, urutan sesuai seeder)
 * - Posisi kecamatan di Excel (nomor urut) digunakan untuk mapping ke ID yang benar
 * - Nama kecamatan di Excel tidak digunakan karena banyak inkonsistensi antar sheet
 * - Tanda "-" pada Excel = 0 (tidak ada tanam)
 */
class RekapHarianTanamSeeder extends Seeder
{
    public function run(): void
    {
        DB::table('rekap_harian_tanam')->truncate();
        DB::table('rekap_bulanan_tanam')->truncate();
        DB::table('rekap_tahunan_tanam')->truncate();

        $validKecamatanIds = DB::table('kecamatan')->pluck('id')->toArray();

        $allData = $this->getData();

        $filtered = array_filter($allData, function($row) use ($validKecamatanIds) {
            return in_array($row['kecamatan_id'], $validKecamatanIds);
        });

        $filtered = array_map(function($row) {
            if (!isset($row['total_ltt'])) {
                $row['total_ltt'] = ($row['total_tanam'] ?? 0) + ($row['oplah'] ?? 0) + ($row['gogo'] ?? 0) + ($row['csr'] ?? 0);
            }
            return $row;
        }, $filtered);

        $chunks = array_chunk(array_values($filtered), 200);
        foreach ($chunks as $chunk) {
            DB::table('rekap_harian_tanam')->insert($chunk);
        }

        $this->command->info('✅ RekapHarianTanamSeeder: ' . count($filtered) . ' records inserted.');
        $this->command->info('🔄 Sinkronisasi rekap bulanan dan tahunan...');

        $groups = DB::table('rekap_harian_tanam')
            ->selectRaw('kabupaten_id, YEAR(tanggal) as tahun')
            ->distinct()
            ->get();

        foreach ($groups as $group) {
            \App\Models\RekapHarianTanam::updateRekapBulananFor($group->kabupaten_id, $group->tahun);
        }

        $this->command->info('✅ Sinkronisasi rekap bulanan & tahunan selesai.');
    }

